const observers = new Map();

export function initialize(dotnetHelper, sentinelElement, rootElement) {
    const observer = new IntersectionObserver(
        entries => {
            const entry = entries[0];
            if (entry.isIntersecting) {
                dotnetHelper.invokeMethodAsync("OnSentinelVisible");
            }
        },
        { root: rootElement, threshold: 0 }
    );

    observer.observe(sentinelElement);
    observers.set(sentinelElement, observer);
}

export function dispose(sentinelElement) {
    const observer = observers.get(sentinelElement);
    if (observer) {
        observer.disconnect();
        observers.delete(sentinelElement);
    }
}

@typeparam TItem
@implements IAsyncDisposable
@inject IJSRuntime JS

<div @ref="_scrollContainer" class="infinite-scroll-container">
    @foreach (var item in Items)
    {
        @ChildContent(item)
    }

    @if (HasMore)
    {
        <div @ref="_sentinel" class="infinite-scroll-sentinel">
            @if (_isLoading)
            {
                <div class="infinite-scroll-spinner" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            }
        </div>
    }
</div>

@code {
    private ElementReference _scrollContainer;
    private ElementReference _sentinel;
    private IJSObjectReference? _module;
    private DotNetObjectReference<InfiniteScrollList<TItem>>? _dotnetRef;
    private bool _isLoading;
    private bool _initialized;

    [Parameter, EditorRequired]
    public IReadOnlyList<TItem> Items { get; set; } = [];

    [Parameter, EditorRequired]
    public bool HasMore { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnLoadMore { get; set; }

    [Parameter, EditorRequired]
    public RenderFragment<TItem> ChildContent { get; set; } = default!;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotnetRef = DotNetObjectReference.Create(this);
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./js/infinite-scroll.js");
        }

        if (HasMore && _module is not null && !_initialized)
        {
            await _module.InvokeVoidAsync("initialize", _dotnetRef, _sentinel, _scrollContainer);
            _initialized = true;
        }
    }

    [JSInvokable]
    public async Task OnSentinelVisible()
    {
        if (_isLoading || !HasMore)
            return;

        _isLoading = true;
        StateHasChanged();

        await OnLoadMore.InvokeAsync();

        _isLoading = false;
        StateHasChanged();
    }

    public async ValueTask DisposeAsync()
    {
        if (_module is not null)
        {
            try
            {
                if (_initialized)
                {
                    await _module.InvokeVoidAsync("dispose", _sentinel);
                }
                await _module.DisposeAsync();
            }
            catch (JSDisconnectedException)
            {
                // Circuit already gone — safe to ignore.
            }
        }
        _dotnetRef?.Dispose();
    }
}

.infinite-scroll-container {
    overflow-y: auto;
    max-height: 80vh;
}

.infinite-scroll-sentinel {
    display: flex;
    justify-content: center;
    padding: 1rem 0;
    min-height: 1px;
}

.infinite-scroll-spinner {
    width: 2rem;
    height: 2rem;
    border: 0.25rem solid currentColor;
    border-right-color: transparent;
    border-radius: 50%;
    animation: infinite-scroll-spin 0.75s linear infinite;
}

@keyframes infinite-scroll-spin {
    to { transform: rotate(360deg); }
}

